function tokenizeCommand2(cmd) {
  const tokens = [];
  let current = "";
  let inQuote = false;
  let quoteChar = "";
  let escaped = false;
  for (let i2 = 0;i2 < cmd.length; i2++) {
    const char = cmd[i2];
    if (escaped) {
      current += char;
      escaped = false;
      continue;
    }
    if (char === "\\") {
      escaped = true;
      continue;
    }
    if ((char === "'" || char === '"') && !inQuote) {
      inQuote = true;
      quoteChar = char;
    } else if (char === quoteChar && inQuote) {
      inQuote = false;
      quoteChar = "";
    } else if (char === " " && !inQuote) {
      if (current) {
        tokens.push(current);
        current = "";
      }
    } else {
      current += char;
    }
  }
  if (current)
    tokens.push(current);
  return tokens;
}
