class ConcurrencyManager {
  config;
  counts = new Map;
  queues = new Map;
  constructor(config3) {
    this.config = config3;
  }
  getConcurrencyLimit(model) {
    const modelLimit = this.config?.modelConcurrency?.[model];
    if (modelLimit !== undefined) {
      return modelLimit === 0 ? Infinity : modelLimit;
    }
    const provider = model.split("/")[0];
    const providerLimit = this.config?.providerConcurrency?.[provider];
    if (providerLimit !== undefined) {
      return providerLimit === 0 ? Infinity : providerLimit;
    }
    const defaultLimit = this.config?.defaultConcurrency;
    if (defaultLimit !== undefined) {
      return defaultLimit === 0 ? Infinity : defaultLimit;
    }
    return 5;
  }
  async acquire(model) {
    const limit = this.getConcurrencyLimit(model);
    if (limit === Infinity) {
      return;
    }
    const current = this.counts.get(model) ?? 0;
    if (current < limit) {
      this.counts.set(model, current + 1);
      return;
    }
    return new Promise((resolve5, reject) => {
      const queue = this.queues.get(model) ?? [];
      const entry = {
        resolve: () => {
          if (entry.settled)
            return;
          entry.settled = true;
          resolve5();
        },
        rawReject: reject,
        settled: false
      };
      queue.push(entry);
      this.queues.set(model, queue);
    });
  }
  release(model) {
    const limit = this.getConcurrencyLimit(model);
    if (limit === Infinity) {
      return;
    }
    const queue = this.queues.get(model);
    while (queue && queue.length > 0) {
      const next = queue.shift();
      if (!next.settled) {
        next.resolve();
        return;
      }
    }
    const current = this.counts.get(model) ?? 0;
    if (current > 0) {
      this.counts.set(model, current - 1);
    }
  }
  cancelWaiters(model) {
    const queue = this.queues.get(model);
    if (queue) {
      for (const entry of queue) {
        if (!entry.settled) {
          entry.settled = true;
          entry.rawReject(new Error(`Concurrency queue cancelled for model: ${model}`));
        }
      }
      this.queues.delete(model);
    }
  }
  clear() {
    for (const [model] of this.queues) {
      this.cancelWaiters(model);
    }
    this.counts.clear();
    this.queues.clear();
  }
  getCount(model) {
    return this.counts.get(model) ?? 0;
  }
  getQueueLength(model) {
    return this.queues.get(model)?.length ?? 0;
  }
}

