function isFactory(source) {
  return typeof source === "function";
}
function buildAgent(source, model, categories, gitMasterConfig) {
  const base = isFactory(source) ? source(model) : source;
  const categoryConfigs = categories ? { ...DEFAULT_CATEGORIES, ...categories } : DEFAULT_CATEGORIES;
  const agentWithCategory = base;
  if (agentWithCategory.category) {
    const categoryConfig = categoryConfigs[agentWithCategory.category];
    if (categoryConfig) {
      if (!base.model) {
        base.model = categoryConfig.model;
      }
      if (base.temperature === undefined && categoryConfig.temperature !== undefined) {
        base.temperature = categoryConfig.temperature;
      }
      if (base.variant === undefined && categoryConfig.variant !== undefined) {
        base.variant = categoryConfig.variant;
      }
    }
  }
  if (agentWithCategory.skills?.length) {
    const { resolved } = resolveMultipleSkills(agentWithCategory.skills, { gitMasterConfig });
    if (resolved.size > 0) {
      const skillContent = Array.from(resolved.values()).join(`

`);
      base.prompt = skillContent + (base.prompt ? `

` + base.prompt : "");
    }
  }
  return base;
}
