import { promises as fs10 } from "fs";
import { join as join36, basename as basename5 } from "path";
import { homedir as homedir13 } from "os";
async function loadCommandsFromDir(commandsDir, scope, visited = new Set, prefix = "") {
  try {
    await fs10.access(commandsDir);
  } catch {
    return [];
  }
  let realPath;
  try {
    realPath = await fs10.realpath(commandsDir);
  } catch (error45) {
    log(`Failed to resolve command directory: ${commandsDir}`, error45);
    return [];
  }
  if (visited.has(realPath)) {
    return [];
  }
  visited.add(realPath);
  let entries;
  try {
    entries = await fs10.readdir(commandsDir, { withFileTypes: true });
  } catch (error45) {
    log(`Failed to read command directory: ${commandsDir}`, error45);
    return [];
  }
  const commands = [];
  for (const entry of entries) {
    if (entry.isDirectory()) {
      if (entry.name.startsWith("."))
        continue;
      const subDirPath = join36(commandsDir, entry.name);
      const subPrefix = prefix ? `${prefix}:${entry.name}` : entry.name;
      const subCommands = await loadCommandsFromDir(subDirPath, scope, visited, subPrefix);
      commands.push(...subCommands);
      continue;
    }
    if (!isMarkdownFile(entry))
      continue;
    const commandPath = join36(commandsDir, entry.name);
    const baseCommandName = basename5(entry.name, ".md");
    const commandName = prefix ? `${prefix}:${baseCommandName}` : baseCommandName;
    try {
      const content = await fs10.readFile(commandPath, "utf-8");
      const { data, body } = parseFrontmatter(content);
      const wrappedTemplate = `<command-instruction>
${body.trim()}
</command-instruction>

<user-request>
$ARGUMENTS
</user-request>`;
      const formattedDescription = `(${scope}) ${data.description || ""}`;
      const isOpencodeSource = scope === "opencode" || scope === "opencode-project";
      const definition = {
        name: commandName,
        description: formattedDescription,
        template: wrappedTemplate,
        agent: data.agent,
        model: sanitizeModelField(data.model, isOpencodeSource ? "opencode" : "claude-code"),
        subtask: data.subtask,
        argumentHint: data["argument-hint"],
        handoffs: data.handoffs
      };
      commands.push({
        name: commandName,
        path: commandPath,
        definition,
        scope
      });
    } catch (error45) {
      log(`Failed to parse command: ${commandPath}`, error45);
      continue;
    }
  }
  return commands;
}
function commandsToRecord(commands) {
  const result = {};
  for (const cmd of commands) {
    const { name: _name, argumentHint: _argumentHint, ...openCodeCompatible } = cmd.definition;
    result[cmd.name] = openCodeCompatible;
  }
  return result;
}
async function loadUserCommands() {
  const userCommandsDir = join36(getClaudeConfigDir(), "commands");
  const commands = await loadCommandsFromDir(userCommandsDir, "user");
  return commandsToRecord(commands);
}
async function loadProjectCommands() {
  const projectCommandsDir = join36(process.cwd(), ".claude", "commands");
  const commands = await loadCommandsFromDir(projectCommandsDir, "project");
  return commandsToRecord(commands);
}
async function loadOpencodeGlobalCommands() {
  const opencodeCommandsDir = join36(homedir13(), ".config", "opencode", "command");
  const commands = await loadCommandsFromDir(opencodeCommandsDir, "opencode");
  return commandsToRecord(commands);
}
async function loadOpencodeProjectCommands() {
  const opencodeProjectDir = join36(process.cwd(), ".opencode", "command");
  const commands = await loadCommandsFromDir(opencodeProjectDir, "opencode-project");
  return commandsToRecord(commands);
}
